    ["RESISTANCE_TOOLTIP_SUBTEXT"] = { en = "Improves resistance to %s-based attacks, spells, and abilities\\n\\nAverage resistance versus a level %d enemy: |cffffffff%s%%|r", it = "Migliora la resistenza agli attacchi, agli incantesimi e alle abilità basati su %s\\n\\nResistenza media contro un nemico di livello %d: |cffffffff%s%%|r" },
    ["VOICE_CHAT_MODE_DISCORD"] = { en = "In-Game Voice (Discord)", it = "Voce di gioco (Discord)" },
    ["OPTION_TOOLTIP_VOICE_CHAT_SERVICE_DISCORD"] = { en = "In-Game Voice (Discord)\\n\\nUses World of Warcraft's built-in voice chat powered by Discord when you are the group leader.\\n\\nYou can link your Discord account to inherit Discord keybind and volume settings (optional, under Social settings).\\n\\nOther players do not require a Discord account to join.\\n\\nDoes not support Text-to-Speech or Speech-to-Text.", it = "Voce di gioco (Discord)\\n\\nUsa la chat vocale integrata di World of Warcraft, fornita da Discord, quando sei il capogruppo.\\n\\nPuoi collegare il tuo account Discord per ereditare le impostazioni di associazione tasti e volume di Discord (opzionale, nelle impostazioni sociali).\\n\\nGli altri giocatori non hanno bisogno di un account Discord per partecipare.\\n\\nNon supporta la sintesi vocale né il riconoscimento vocale." },
    ["VOICE_CHAT_MODE_LEGACY"] = { en = "In-Game Voice (Legacy)", it = "Voce di gioco (classica)" },
    ["OPTION_TOOLTIP_VOICE_CHAT_SERVICE_LEGACY"] = { en = "In-Game Voice (Legacy)\\n\\nUses World of Warcraft's older voice chat service when you are the group leader.\\n\\nUse this option if you require Text-to-Speech or Speech-to-Text.", it = "Voce di gioco (classica)\\n\\nUsa il vecchio servizio di chat vocale di World of Warcraft quando sei il capogruppo.\\n\\nUsa questa opzione se ti serve la sintesi vocale o il riconoscimento vocale." },
    ["CURRENCY_FILTER_TYPE_TRANSFERABLE_TOOLTIP"] = { en = "Include currencies owned by other members of your Account", it = "Includi le valute possedute dagli altri membri del tuo account" },
    ["PHRASES_DUNGEON_INCOMING"] = { en = "Incoming!", it = "In arrivo!" },
    ["CR_EXPERTISE_TOOLTIP"] = { en = "Increase the chance |cFFFFFFFFMelee|r attacks are not |cFFFFFFFFDodged|r or |cFFFFFFFFParried|r by %s\\n\\n|cFFFF5A5ARaid Boss|r|cffBCBCBC chance to:\\n  6.50%% Dodge\\n16.50%% Parry\\n\\n|r|cFF52E31EEqual-Level Creature|r|cffBCBCBC chance to:\\n  5.00%% Dodge\\n  5.00%% Parry|r", it = "Aumenta la probabilità che gli attacchi |cFFFFFFFFin mischia|r non vengano |cFFFFFFFFschivati|r né |cFFFFFFFFparati|r del %s\\n\\n|cFFFF5A5ABoss delle incursioni|r|cffBCBCBC probabilità di:\\n  6.50%% Schivata\\n16.50%% Parata\\n\\n|r|cFF52E31ECreatura dello stesso livello|r|cffBCBCBC probabilità di:\\n  5.00%% Schivata\\n  5.00%% Parata|r" },
    ["TRAINING_POINTS_TUTORIAL"] = { en = "Increase your pets loyalty and level to gain Training Points.", it = "Aumenta la fedeltà e il livello del tuo famiglio per ottenere punti addestramento." },
    ["STAT_HUNTER_PET_CRIT_BONUS"] = { en = "Increased by 100%% of |cFFFFFFFFMaster's Critical Strike Chance|r\\n\\n|cFFBCBCBCMelee critical strikes deal 100%% increased damage\\n\\nSpell and Healing critical strikes are 50%% more effective\\n\\nMost periodic effects can critically strike|r", it = "Aumentato del 100%% della |cFFFFFFFFprobabilità di critico del maestro|r\\n\\n|cFFBCBCBCI colpi critici in mischia infliggono il 100%% di danni aggiuntivi\\n\\nI colpi critici degli incantesimi e delle cure sono il 50%% più efficaci\\n\\nLa maggior parte degli effetti periodici può infliggere colpi critici|r" },
    ["STAT_WARLOCK_PET_CRIT_BONUS"] = { en = "Increased by 100%% of |cFFFFFFFFMaster's Spell Critical Strike Chance|r\\n\\n|cFFBCBCBCMelee critical strikes deal 100%% increased damage\\n\\nSpell and Healing critical strikes are 50%% more effective\\n\\nMost periodic effects can critically strike|r", it = "Aumentato del 100%% della |cFFFFFFFFprobabilità di critico degli incantesimi del maestro|r\\n\\n|cFFBCBCBCI colpi critici in mischia infliggono il 100%% di danni aggiuntivi\\n\\nI colpi critici degli incantesimi e delle cure sono il 50%% più efficaci\\n\\nLa maggior parte degli effetti periodici può infliggere colpi critici|r" },
    ["STAT_HUNTER_CRIT_BONUS"] = { en = "Increased by |cFFFFFFFFAgility|r for Attacks\\nIncreased by |cFFFFFFFFIntellect|r for Spells\\n\\n|cFFBCBCBCMelee and Ranged critical strikes deal 100%% increased damage\\n\\nSpell and Healing critical strikes are 50%% more effective\\n\\nMost periodic effects can critically strike|r", it = "Aumentato in base all'|cFFFFFFFFAgilità|r per gli attacchi\\nAumentato in base all'|cFFFFFFFFIntelletto|r per gli incantesimi\\n\\n|cFFBCBCBCI colpi critici in mischia e a distanza infliggono il 100%% di danni aggiuntivi\\n\\nI colpi critici degli incantesimi e delle cure sono il 50%% più efficaci\\n\\nLa maggior parte degli effetti periodici può infliggere colpi critici|r" },
    ["STAT_CRIT_BONUS"] = { en = "Increased by |cFFFFFFFFAgility|r for Attacks\\nIncreased by |cFFFFFFFFIntellect|r for Spells\\n\\n|cFFBCBCBCMelee critical strikes deal 100%% increased damage\\n\\nSpell and Healing critical strikes are 50%% more effective\\n\\nMost periodic effects can critically strike|r", it = "Aumentato in base all'|cFFFFFFFFAgilità|r per gli attacchi\\nAumentato in base all'|cFFFFFFFFIntelletto|r per gli incantesimi\\n\\n|cFFBCBCBCI colpi critici in mischia infliggono il 100%% di danni aggiuntivi\\n\\nI colpi critici degli incantesimi e delle cure sono il 50%% più efficaci\\n\\nLa maggior parte degli effetti periodici può infliggere colpi critici|r" },
    ["STAT_WARRIOR_CRIT_BONUS"] = { en = "Increased by |cFFFFFFFFAgility|r for Attacks\\r\\n\\n|cFFBCBCBCMelee and Ranged critical strikes deal 100%% increased damage\\n\\nSpell and Healing critical strikes are 50%% more effective\\n\\nMost periodic effects can critically strike|r", it = "Aumentato in base all'|cFFFFFFFFAgilità|r per gli attacchi\\r\\n\\n|cFFBCBCBCI colpi critici in mischia e a distanza infliggono il 100%% di danni aggiuntivi\\n\\nI colpi critici degli incantesimi e delle cure sono il 50%% più efficaci\\n\\nLa maggior parte degli effetti periodici può infliggere colpi critici|r" },
    ["STAT_ROGUE_CRIT_BONUS"] = { en = "Increased by |cFFFFFFFFAgility|r for Attacks|r\\n\\n|cFFBCBCBCMelee and Ranged critical strikes deal 100%% increased damage\\n\\nSpell and Healing critical strikes are 50%% more effective\\n\\nMost periodic effects can critically strike|r", it = "Aumentato in base all'|cFFFFFFFFAgilità|r per gli attacchi|r\\n\\n|cFFBCBCBCI colpi critici in mischia e a distanza infliggono il 100%% di danni aggiuntivi\\n\\nI colpi critici degli incantesimi e delle cure sono il 50%% più efficaci\\n\\nLa maggior parte degli effetti periodici può infliggere colpi critici|r" },
    ["MANA_SPIRIT_TOOLTIP"] = { en = "Increases Health regeneration per 5 seconds by %d and Mana regeneration per 5 seconds by %d. Your total Health regenerated per 5 seconds is %d and your total Mana regeneration per 5 seconds is %d. Mana regeneration from Spirit is halted for 5 seconds after using a spell or ability that costs Mana.", it = "Aumenta la rigenerazione della Salute ogni 5 secondi di %d e la rigenerazione del Mana ogni 5 secondi di %d. La Salute totale rigenerata ogni 5 secondi è %d e la rigenerazione totale del Mana è %d. La rigenerazione del Mana derivante dallo Spirito si interrompe per 5 secondi dopo aver usato un incantesimo o un'abilità che costa Mana." },
    ["ITEM_MOD_ALCHEMY"] = { en = "Increases alchemy skill by %s.", it = "Aumenta l'abilità di alchimia di %s." },
    ["ITEM_MOD_ARCANE_DAMAGE_DONE"] = { en = "Increases arcane damage done by up to %s.", it = "Aumenta i danni arcani inflitti fino a %s." },
