    ["HUNTER_AGILITY_TOOLTIP"] = { en = "Increases |cFFFFFFFFDodge|r chance by %.1f%%\\nIncreases |cFFFFFFFFArmor|r by %d\\nIncreases |cFFFFFFFFCritical Strike|r chance by %.1f%%\\nIncreases |cFFFFFFFFAttack Power|r by %d\\nIncreases |cFFFFFFFFRanged Attack Power|r by %d", it = "Aumenta la probabilità di |cFFFFFFFFschivata|r di %.1f%%\\nAumenta l'|cFFFFFFFFarmatura|r di %d\\nAumenta la probabilità di |cFFFFFFFFcolpo critico|r di %.1f%%\\nAumenta la |cFFFFFFFFpotenza d'attacco|r di %d\\nAumenta la |cFFFFFFFFpotenza d'attacco a distanza|r di %d" },
    ["DEFAULT_STATDEFENSE_TOOLTIP"] = { en = "Increases |cFFFFFFFFDodge|r, |cFFFFFFFFBlock|r, and |cFFFFFFFFParry|r chance by %.2f%%, and decreases chance to be |cFFFFFFFFHit|r or |cFFFFFFFFCritically Hit|r by %.2f%%\\n\\n|cffBCBCBCCritical Strikes from creatures deal 200%% damage. Creatures 3+ levels above you can land Crushing Blows for 150%% damage\\n\\n|cffBCBCBCAt 440 Defense, cannot be Critically Hit by|r |cFFFF5A5ARaid Bosses|r |cFFBCBCBC(-5.60%% Critical Strike chance)|r", it = "Aumenta le probabilità di |cFFFFFFFFschivata|r, |cFFFFFFFFblocco|r e |cFFFFFFFFparata|r di %.2f%% e riduce la probabilità di subire un |cFFFFFFFFcolpo|r o un |cFFFFFFFFcolpo critico|r di %.2f%%\\n\\n|cffBCBCBCC I colpi critici delle creature infliggono il 200%% dei danni. Le creature di almeno 3 livelli superiori al tuo possono sferrare colpi devastanti che infliggono il 150%% dei danni\\n\\n|cffBCBCBCCon 440 Difesa, non puoi subire colpi critici da|r |cFFFF5A5ABoss dei raid|r |cFFBCBCBC(-5.60%% probabilità di colpo critico)|r" },
